def facts():
    (p,) = [L.plan(a) for a in asts(T(CH).sum((0, 2, 3)))]
    kind, rows, cols = R._view(p)
    laid = R._laid(p, rows, cols, R._wide(cols), out=False)
    split = R._split_reduction(p)
    return {
        "laid": laid > 0,
        "parts": [[U.extent(r) for r in rs] for rs in split.reductions.values()],
    }
